For preview branch setup, I’d treat branch creation as asynchronous from an app-readiness perspective:

```ts
async function waitForNeonBranchReady(query: () => Promise<unknown>) {
  const deadline = Date.now() + 60_000
  let attempt = 0

  while (Date.now() < deadline) {
    try {
      await query() // SELECT 1
      return
    } catch (err) {
      const delay = Math.min(1000 * 2 ** attempt++, 5000)
      await new Promise((r) => setTimeout(r, delay))
    }
  }

  throw new Error("Neon preview branch did not become ready within 60s")
}
```

